int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_sb_info *sbi = EXT4_SB(inode->i_sb);
    struct ext4_orphan_list *orphan;
    int err = 0;

    if (!EXT4_HAS_JOURNAL(inode->i_sb))
        return 0;

    mutex_lock(&sbi->s_orphan_lock);

    if (!ei->i_dtime) {
        err = -ENOENT;
        goto out;
    }

    if (sbi->s_orphan) {
        orphan = sbi->s_orphan;
        if (orphan->ino == inode->i_ino) {
            sbi->s_orphan = orphan->next;
            kfree(orphan);
        } else {
            while (orphan->next && orphan->next->ino != inode->i_ino)
                orphan = orphan->next;

            if (orphan->next) {
                struct ext4_orphan_list *tmp = orphan->next;
                orphan->next = tmp->next;
                kfree(tmp);
            } else {
                err = -ENOENT;
                goto out;
            }
        }
    }

    if (handle) {
        err = ext4_mark_inode_dirty(handle, inode);
        if (err)
            goto out;
    }

    ei->i_dtime = 0;

out:
    mutex_unlock(&sbi->s_orphan_lock);
    return err;
}

